    // Decreases: The length of dst (or src or mask) to ensure termination.
    // Invariant: At the start of each iteration, result has length i and
    //            for all j < i, result[j] is correctly populated.
    //            mask.len() == dst.len() == src.len().

    let mut result = Vec::with_capacity(dst.len());

    // Loop invariant: result has length i and for all j < i, result[j] is correctly populated.
